logical_plan:
Sink
  Project [service, window_start, err]
    Aggregate group_by=[service] aggs=[Avg(value)]
      Window Tumble { size_ns: 1000000000 }
        Filter Binary { left: Column("name"), op: Like, right: Literal(Text("%error_rate%")) }
          Scan metrics [*]

optimized_logical_plan:
Sink
  Aggregate group_by=[service] aggs=[Avg(value)]
    Window Tumble { size_ns: 1000000000 }
      Filter Binary { left: Column("name"), op: Like, right: Literal(Text("%error_rate%")) }
        Scan metrics [service, name, value, event_time]
